#include <cuda_runtime.h>
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <string>
#include <vector>
#define BEM_TABLE_QUAL static __device__ __constant__
#define BEM_HD static __device__ __forceinline__
#include "bem_real_solver.h"
struct Case{double vx,vy,theta,hint,root,gl,gr;int node,multi,near;};struct Out{double root,gl,gr,residual,knot_distance;uint8_t status;};
static std::vector<std::string> fields(const std::string&s){std::vector<std::string>v;std::stringstream q(s);std::string x;while(std::getline(q,x,','))v.push_back(x);return v;}
static std::vector<Case>load(const std::string&p,const std::string&split){std::ifstream f(p);std::string line;std::getline(f,line);std::vector<Case>v;while(std::getline(f,line)){auto c=fields(line);if(c.size()<22||c[2]!=split)continue;v.push_back({stod(c[4]),stod(c[5]),stod(c[6]),stod(c[7]),stod(c[11]),stod(c[16]),stod(c[17]),stoi(c[3]),stoi(c[9])>1,stod(c[18])<=1e-3});}return v;}
__device__ double knot_distance_rad(double phi,double theta,unsigned node){double alpha=bem_wrap_pi(phi-theta)*(180.0/BEM_PI);unsigned af=bem_node_afid[node],off=bem_af_offset[af],n=bem_af_count[af],lo=0,hi=n-1;while(hi-lo>1){unsigned m=(lo+hi)>>1;if(bem_alpha_deg[off+m]<=alpha)lo=m;else hi=m;}double d=fmin(fabs(alpha-bem_alpha_deg[off+lo]),fabs(alpha-bem_alpha_deg[off+hi]));return d*(BEM_PI/180.0);}
struct Dual{double v,p,x;};
__device__ __forceinline__ Dual C(double v){return{v,0,0};}__device__ __forceinline__ Dual operator+(Dual a,Dual b){return{a.v+b.v,a.p+b.p,a.x+b.x};}__device__ __forceinline__ Dual operator-(Dual a,Dual b){return{a.v-b.v,a.p-b.p,a.x-b.x};}__device__ __forceinline__ Dual operator-(Dual a){return{-a.v,-a.p,-a.x};}__device__ __forceinline__ Dual operator*(Dual a,Dual b){return{a.v*b.v,a.p*b.v+a.v*b.p,a.x*b.v+a.v*b.x};}__device__ __forceinline__ Dual operator/(Dual a,Dual b){double z=1/(b.v*b.v);return{a.v/b.v,(a.p*b.v-a.v*b.p)*z,(a.x*b.v-a.v*b.x)*z};}
__device__ __forceinline__ Dual dsin(Dual a){double c=cos(a.v);return{sin(a.v),c*a.p,c*a.x};}__device__ __forceinline__ Dual dcos(Dual a){double s=-sin(a.v);return{cos(a.v),s*a.p,s*a.x};}__device__ __forceinline__ Dual dexp(Dual a){double e=exp(a.v);return{e,e*a.p,e*a.x};}__device__ __forceinline__ Dual dsqrt(Dual a){double s=sqrt(a.v),q=.5/s;return{s,q*a.p,q*a.x};}__device__ __forceinline__ Dual dabs(Dual a){return a.v<0?-a:a;}__device__ __forceinline__ Dual dacos(Dual a){double q=-1/sqrt(fmax(1e-300,1-a.v*a.v));return{acos(a.v),q*a.p,q*a.x};}
__device__ Dual polar_cl_dual(unsigned node,Dual phi,double theta,int side){unsigned af=bem_node_afid[node],off=bem_af_offset[af],n=bem_af_count[af];double alpha=bem_wrap_pi(phi.v-theta)*(180.0/BEM_PI),key=alpha+side*1e-11;unsigned lo=0,hi=n-1;if(key<=bem_alpha_deg[off])lo=0;else if(key>=bem_alpha_deg[off+n-1])lo=n-2;else{while(hi-lo>1){unsigned m=(lo+hi)>>1;if(bem_alpha_deg[off+m]<=key)lo=m;else hi=m;}}double slope=(bem_cl[off+lo+1]-bem_cl[off+lo])/(bem_alpha_deg[off+lo+1]-bem_alpha_deg[off+lo]),value=bem_cl[off+lo]+(alpha-bem_alpha_deg[off+lo])*slope;return{value,slope*(180.0/BEM_PI)*phi.p,slope*(180.0/BEM_PI)*phi.x};}
__device__ Dual residual_dual(double phi0,double vx0,double vy,double theta,unsigned node,int side){Dual phi{phi0,1,0},vx{vx0,0,1},cl=polar_cl_dual(node,phi,theta,side),s=dsin(phi),co=dcos(phi),as=dabs(s),ft=C(1),fh=C(1);if(as.v>0){Dual et=dexp(C(-bem_node_tip_const[node])/as),eh=dexp(C(-bem_node_hub_const[node])/as);if(et.v>1)et=C(1);if(eh.v>1)eh=C(1);ft=C(2.0/BEM_PI)*dacos(et);fh=C(2.0/BEM_PI)*dacos(eh);}Dual F=ft*fh;if(F.v<1e-4)F=C(1e-4);Dual sigma=C(3.0*bem_node_chord[node]/(2.0*BEM_PI*bem_node_r[node])),cn=cl*co,ct=cl*s,k=sigma*cn/(C(4)*F*s*s),kp;if(fabs(co.v)<1e-15)kp=C(copysign(1e6,ct.v*s.v)*copysign(1.0,vx0));else{kp=sigma*ct/(C(4)*F*s*co);if(vx0<0)kp=-kp;}bool momentum=(phi0>0&&vx0>=0)||(phi0<0&&vx0<0);Dual a;if(momentum){if(k.v<=2.0/3.0)a=k/(C(1)+k);else{Dual t=C(2)*F*k,g1=t-(C(10.0/9.0)-F),g2=t-(C(4.0/3.0)-F)*F,g3=t-(C(25.0/9.0)-C(2)*F);a=fabs(g3.v)<1e-6?C(1)-C(.5)/dsqrt(dabs(g2)):(g1-dsqrt(dabs(g2)))/g3;}return s/(C(1)-a)-co/(C(vy)/vx)*(C(1)-kp);}a=k/(k-C(1));return s*(C(1)-k)-co/(C(vy)/vx)*(C(1)-kp);}
__global__ void kernel(const Case*in,Out*out,size_t n){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;const Case&p=in[i];double x;int ok=bem_solve_algorithm(p.vx,p.vy,p.theta,p.hint,(unsigned)p.node,4,&x),valid=0;for(int k=0;k<2;k++){double f=bem_residual(x,p.vx,p.vy,p.theta,p.node,&valid);Dual d=residual_dual(x,p.vx,p.vy,p.theta,p.node,1);if(!isfinite(f)||!isfinite(d.p)||fabs(d.p)<1e-12)break;double step=f/d.p;if(fabs(step)>1e-4)step=copysign(1e-4,step);x-=step;}double f0=bem_residual(x,p.vx,p.vy,p.theta,p.node,&valid),dist=knot_distance_rad(x,p.theta,(unsigned)p.node);Dual left=residual_dual(x,p.vx,p.vy,p.theta,p.node,-1),right=residual_dual(x,p.vx,p.vy,p.theta,p.node,1);Out o{x,-left.x/left.p,-right.x/right.p,fabs(f0),dist,(uint8_t)(!ok||!valid||!isfinite(left.p)||!isfinite(right.p)||!isfinite(left.x)||!isfinite(right.x))};out[i]=o;}
static double wrap_host(double x){x=fmod(x+BEM_PI,2*BEM_PI);if(x<0)x+=2*BEM_PI;return x-BEM_PI;}static double rel(double a,double b){return fabs(a-b)/fmax(fabs(b),1e-30);}static double quant(std::vector<double>v,double p){std::sort(v.begin(),v.end());return v[(size_t)(p*(v.size()-1))];}
int main(int argc,char**argv){std::string refs,split="cal",outdir="results_raw/bem_gradient";for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--references"))refs=argv[++i];else if(!strcmp(argv[i],"--split"))split=argv[++i];else if(!strcmp(argv[i],"--out"))outdir=argv[++i];}if(refs.empty())return 2;auto r=load(refs,split);if(r.empty())return 3;std::filesystem::create_directories(outdir);Case*di;Out*doo;cudaMalloc(&di,r.size()*sizeof(Case));cudaMalloc(&doo,r.size()*sizeof(Out));cudaMemcpy(di,r.data(),r.size()*sizeof(Case),cudaMemcpyHostToDevice);kernel<<<int((r.size()+255)/256),256>>>(di,doo,r.size());cudaDeviceSynchronize();std::vector<Out>o(r.size());cudaMemcpy(o.data(),doo,o.size()*sizeof(Out),cudaMemcpyDeviceToHost);std::vector<double>root,gl,gr,near,away,multi;size_t nf=0;std::ofstream raw(outdir+"/bem_gradient_"+split+"_samples.csv");raw<<"index,near_knot,multi_root,root_abs,gradient_left_rel,gradient_right_rel,residual,knot_distance_rad,status\n";for(size_t i=0;i<r.size();i++){double er=fabs(wrap_host(o[i].root-r[i].root)),el=rel(o[i].gl,r[i].gl),eright=rel(o[i].gr,r[i].gr);root.push_back(er);gl.push_back(el);gr.push_back(eright);(r[i].near?near:away).push_back(fmax(el,eright));if(r[i].multi)multi.push_back(fmax(el,eright));nf+=o[i].status;raw<<i<<','<<r[i].near<<','<<r[i].multi<<','<<std::setprecision(17)<<er<<','<<el<<','<<eright<<','<<o[i].residual<<','<<o[i].knot_distance<<','<<int(o[i].status)<<'\n';}std::ofstream s(outdir+"/bem_gradient_"+split+"_summary.csv");s<<"group,n,root_max,gradient_median,gradient_p99,gradient_max,nonfinite\n";auto emit=[&](const char*n,const std::vector<double>&v){s<<n<<','<<v.size()<<','<<quant(root,1)<<','<<quant(v,.5)<<','<<quant(v,.99)<<','<<quant(v,1)<<','<<nf<<'\n';};std::vector<double>both=gl;both.insert(both.end(),gr.begin(),gr.end());emit("all_sides",both);emit("near_knot",near);emit("away_from_knot",away);if(!multi.empty())emit("multi_root",multi);std::printf("split=%s n=%zu root_max=%.3e left_max=%.3e right_max=%.3e near_max=%.3e away_max=%.3e nonfinite=%zu\n",split.c_str(),r.size(),quant(root,1),quant(gl,1),quant(gr,1),quant(near,1),quant(away,1),nf);cudaFree(doo);cudaFree(di);return 0;}
